'use strict';
const D=SchoolData,$=s=>document.querySelector(s);let liveSummary=null;let records=null,topic='all',pending=null,importWarnings=[];
const configs=[['school_rating','Как оценивают школьную жизнь','life'],['recreation_rating','Удобно ли отдыхать в рекреациях','spaces'],['space_priorities','Что улучшить в местах отдыха','spaces',true],['media_awareness','Что знают о медиа-классах','life'],['sections','Какие секции посещают','life',true],['information_access','Легко ли найти информацию','life'],['schedule_rating','Удобно ли совмещать уроки и занятия','life'],['improvement_priorities','Какие изменения важнее','ideas',true]];
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function selected(){const g=$('#class-filter').value;if(records!==null)return D.summarize(records.filter(r=>g==='all'||r.group===g));return (liveSummary||window.SchoolInitial)?.groups[g]||D.summarize([]);}
function total(){return records!==null?records.length:((liveSummary||window.SchoolInitial)?.groups.all.participants||0);}
function chart(data,key,title,multi){const d=data.results[key]||{answered:0,items:[]},a=el('article',undefined,'chart');a.append(el('h3',title),el('p',`Ответили: ${d.answered}${multi?' · несколько вариантов; сумма долей может быть больше 100%':''}`,'chart-meta'));if(!d.answered)a.append(el('p','На этот вопрос пока нет ответов.','chart-empty'));for(const item of d.items){const row=el('div',undefined,'bar-row'),label=el('div',undefined,'bar-label'),track=el('div',undefined,'bar-track'),fill=el('div',undefined,'bar-fill');label.append(el('span',item.label),el('span',`${item.count} · ${item.percent}%`));fill.style.width=item.percent+'%';track.setAttribute('aria-hidden','true');track.append(fill);row.append(label,track);a.append(row);}return a;}
function render(){const data=selected();$('#count').textContent=data.participants;const avg=data.average;$('#rating').textContent=avg===null?'—':avg.toLocaleString('ru-RU',{maximumFractionDigits:1})+' / 5';const priorities=data.results.improvement_priorities?.items||[],leaders=priorities.filter(x=>x.count===priorities[0]?.count);$('#priority').textContent=leaders.length?leaders.map(x=>x.label).join(' / '):'—';$('#charts').replaceChildren();$('#empty').hidden=data.participants>0;$('#empty h3').textContent=total()?'В этой группе пока нет ответов':'Исследование начинается с ответов';$('#empty p').textContent=total()?'Выбери другую группу классов или загрузи новые ответы.':'Когда появятся ответы, здесь будут реальные диаграммы и выводы.';if(data.participants)for(const [key,title,t,multi] of configs)if(topic==='all'||topic===t)$('#charts').append(chart(data,key,title,multi));$('#dataset-note').textContent=total()?`Предварительные результаты · ${records===null?(liveSummary?'из Google Forms · обновлено '+new Date(liveSummary.generated_at).toLocaleString('ru-RU'):'сохранённый срез на 6 ноября 2026 года'):'локально загруженная выгрузка'}. Всего анкет: ${total()}. Выбрано: ${data.participants}. Это мнения участников, а не всей школы. ${importWarnings.join(' ')}`:'Результаты пока не загружены.';$('#export').hidden=!data.participants;renderZone();}
$('#import-toggle').addEventListener('click',()=>{const p=$('#import-panel');p.hidden=!p.hidden;$('#import-toggle').setAttribute('aria-expanded',String(!p.hidden));});
$('#class-filter').addEventListener('change',()=>{render();$('#initial-idea').hidden=records!==null||liveSummary!==null||!['all','10–11'].includes($('#class-filter').value);});
document.querySelectorAll('[data-topic]').forEach(b=>b.addEventListener('click',()=>{topic=b.dataset.topic;document.querySelectorAll('[data-topic]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();}));
function status(text,error=false){$('#import-status').textContent=text;$('#import-status').className=error?'error':'';}
$('#csv-file').addEventListener('change',async e=>{pending=null;$('#mapping').hidden=true;const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Файл больше 10 МБ. Выбери CSV меньшего размера.');const text=await file.text();if(text.includes('\uFFFD'))throw Error('Не удалось прочитать кодировку. Сохрани файл как CSV UTF-8.');const parsed=D.parseCSV(text),mapping=D.autoMap(parsed.headers);pending=parsed;showMapping(parsed,mapping);status(`Прочитано строк: ${parsed.rows.length}. Проверь соответствие вопросов и столбцов, затем нажми «Применить».`);}catch(err){status(err.message,true);}});
function showMapping(parsed,mapping){const container=$('#mapping');container.replaceChildren();const grid=el('div',undefined,'mapping-fields');for(const f of D.fields){const label=el('label',f.label),select=el('select');select.dataset.field=f.key;const blank=el('option','Не загружать');blank.value='-1';select.append(blank);parsed.headers.forEach((h,i)=>{const o=el('option',h||`Столбец ${i+1}`);o.value=String(i);select.append(o);});select.value=String(mapping[f.key]);label.append(select);grid.append(label);}const apply=el('button','Применить ответы','button dark');apply.type='button';apply.addEventListener('click',()=>{try{if(!pending)throw Error('Сначала выбери CSV.');const m=Object.fromEntries([...container.querySelectorAll('select')].map(s=>[s.dataset.field,Number(s.value)]));const result=D.convert(pending,m);records=result.records;importWarnings=result.warnings;render();status(`Загружено ${records.length} анкет. Данные хранятся только до перезагрузки страницы. ${importWarnings.join(' ')}`);container.hidden=true;pending=null;}catch(err){status(err.message,true);}});container.append(el('h3','Какие столбцы использовать'),el('p','Выбери «Не загружать», если вопрос отсутствует. Время отправки и электронная почта не нужны.'),grid,apply);container.hidden=false;}
const zones={rest:{kicker:'РЕКРЕАЦИИ',title:'Перемена тоже важна',body:'В школе есть рекреации с диванами. В анкете спрашиваем, удобно ли там отдыхать и чего ученикам не хватает.',key:'recreation_rating'},media:{kicker:'МЕДИА-КЛАССЫ',title:'Пространство для интереса',body:'В школе есть медиа-классы. Исследуем, знают ли о них ученики и участвуют ли в занятиях. Программу и расписание стоит уточнять в школе.',key:'media_awareness'},sport:{kicker:'СПОРТИВНЫЕ СЕКЦИИ',title:'Движение на свой вкус',body:'По информации автора, доступны футбол, дзюдо и скалолазание. Узнаём, какие секции посещают участники. Схема не указывает место проведения занятий.',key:'sections'}};let zone='rest';
function renderZone(){$('#initial-idea').hidden=records!==null||liveSummary!==null||!['all','10–11'].includes($('#class-filter').value);const z=zones[zone],box=$('#zone-detail');box.replaceChildren(el('p',z.kicker,'zone-kicker'),el('h3',z.title),el('p',z.body));const d=selected().results[z.key]||{answered:0,items:[]};box.append(el('p',d.answered?`В выбранной группе на связанный вопрос ответили: ${d.answered}.`:'Ответы по этой теме ещё не загружены.'));if(d.items.length){const list=el('ul',undefined,'zone-results');for(const item of d.items)list.append(el('li',`${item.label} — ${item.count} (${item.percent}%)`));box.append(list);}const a=el('a','К результатам исследования ↗');a.href='#results';box.append(a);window.dispatchEvent(new Event('school-data-change'));}
document.querySelectorAll('[data-zone]').forEach(b=>b.addEventListener('click',()=>{zone=b.dataset.zone;document.querySelectorAll('[data-zone]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderZone();}));
$('#export').addEventListener('click',()=>{const data=selected(),summary={project:'Школа глазами учеников',exported_at:new Date().toISOString(),class_filter:$('#class-filter').value,participants:data.participants,average:data.average,note:'Агрегированные ответы выбранной группы; свободные ответы не включены. Это не дата сбора анкет.',results:data.results};const url=URL.createObjectURL(new Blob([JSON.stringify(summary,null,2)],{type:'application/json;charset=utf-8'})),a=el('a');a.href=url;a.download='school-summary.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('#load-survey').addEventListener('click',()=>{const frame=$('#survey-frame');frame.src='https://docs.google.com/forms/d/e/1FAIpQLSf2jkWIqV353xPg1wf_8hfU8tEHmEkEWQ946u5a4DtgbUjpbQ/viewform?embedded=true';frame.hidden=false;$('#survey-placeholder').hidden=true;});
render();

window.addEventListener('school-summary',e=>{liveSummary=e.detail;render();});
window.addEventListener('school-show-live',()=>{records=null;importWarnings=[];render();});
$('#load-map').addEventListener('click',()=>{const map=$('#map-frame');map.src='https://yandex.ru/map-widget/v1/?oid=1076737941&ol=biz&z=16';map.hidden=false;$('#load-map').hidden=true;});
$('#school-photo').addEventListener('error',()=>{$('#school-photo').hidden=true;$('#photo-fallback').hidden=false;});
